            vis[i][j]=True; comps=[]
            while st:
                a,b=st.pop(); comps.append((a,b))
                for da in(-1,0,1):
                    for db_ in(-1,0,1):
                        x,y=a+da,b+db_
                        if 0<=x<h and 0<=y<w and not vis[x][y] and inp[x][y]!=bg:
                            vis[x][y]=True; st.append((x,y))
            rs=[a for a,b in comps]; cs=[b for a,b in comps]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            v=I[r0,c0]
            t=all(I[r0,k2]==v for k2 in range(c0,c1+1)); b_=all(I[r1,k2]==v for k2 in range(c0,c1+1))
            l_=all(I[k3,c0]==v for k3 in range(r0,r1+1)); r_=all(I[k3,c1]==v for k3 in range(r0,r1+1))
            ok=all(I[a][b2]==bg for a in range(r0+1,r1) for b2 in range(c0+1,c1))
            if t and b_ and l_ and r_ and ok:
                for k2 in range(c0,c1+1): res[r0,k2],res[r1,k2]=3,3
                for k3 in range(r0,r1+1): res[k3,c0],res[k3,c1]=3,3
    return [list(map(int,r)) for r in res]
